// Reports the ten most frequent words in a UTF-8 text file.
// A word is a maximal run of ASCII letters and digits; every other byte
// separates words. Counting ignores case and output is lower case.

const TOP = 10;

function isWordByte(c: number): boolean {
  return (c >= 0x30 && c <= 0x39) || // 0-9
    (c >= 0x41 && c <= 0x5a) || // A-Z
    (c >= 0x61 && c <= 0x7a); // a-z
}

// Words are pure ASCII, so lower-casing bytes and decoding is exact.
function lowerWord(bytes: Uint8Array): string {
  const lower = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) {
    const c = bytes[i];
    lower[i] = c >= 0x41 && c <= 0x5a ? c + 0x20 : c;
  }
  return new TextDecoder().decode(lower);
}

function compareBytes(a: string, b: string): number {
  // Every word is ASCII, so UTF-16 code unit order equals byte order.
  return a < b ? -1 : a > b ? 1 : 0;
}

const path = Deno.args[0];
if (path === undefined) {
  console.error("usage: deno run main.ts <file>");
  Deno.exit(2);
}

const data = await Deno.readFile(path);
const counts = new Map<string, number>();

let start = -1;
for (let i = 0; i <= data.length; i++) {
  // The sentinel past the end closes a word that runs to end of file.
  const c = i < data.length ? data[i] : 0x20;
  if (isWordByte(c)) {
    if (start < 0) start = i;
  } else if (start >= 0) {
    const word = lowerWord(data.subarray(start, i));
    counts.set(word, (counts.get(word) ?? 0) + 1);
    start = -1;
  }
}

const top = [...counts]
  .sort(([wa, ca], [wb, cb]) => cb - ca || compareBytes(wa, wb))
  .slice(0, TOP);

if (top.length > 0) {
  console.log(top.map(([word, count]) => `${word} ${count}`).join("\n"));
}

